workflows.trigger:
name: Site Factory Production Deploy
on:
  workflow_call:
    inputs:
      site_key: {required: true, type: string}
      launch_key: {required: false, type: string, default: ''}
      scope_key: {required: false, type: string, default: ''}
      expected_revision: {required: true, type: string}
      source_snapshot_issue: {required: false, type: string, default: ''}
    secrets:
      CLOUDFLARE_API_TOKEN: {required: true}
      CLOUDFLARE_ACCOUNT_ID: {required: true}
  workflow_dispatch:
    inputs:
      site_key: {description: Registered site key, required: true, type: string}
      launch_key: {description: Exact registered launch for scoped coverage, required: false, type: string}
      scope_key: {description: Exact registered scope for scoped coverage, required: false, type: string}
      expected_revision: {description: Full independently approved target commit SHA, required: true, type: string}
      source_snapshot_issue: {description: Existing request issue for durable production receipts, required: true, type: string}
      indexnow_only: {description: Verify and submit the already public revision without deploying, required: false, type: boolean, default: false}
  issues:
    types: [opened, reopened]
permissions: {}
concurrency:
  group: "${{ (inputs.site_key == 'goyang-flower-v2' || contains(github.event.issue.body, 'SITE_KEY: goyang-flower-v2')) && format('site-staging-{0}', github.repository) || format('site-production-{0}', github.repository) }}"
  cancel-in-progress: false

name: Site Factory Isolated Staging Preview
on:
  workflow_call:
    inputs:
      site_key: {required: true, type: string}
      launch_key: {required: false, type: string, default: ''}
      scope_key: {required: false, type: string, default: ''}
      expected_revision: {required: true, type: string}
      source_snapshot_issue: {required: false, type: string, default: ''}
    secrets:
      CLOUDFLARE_API_TOKEN: {required: true}
      CLOUDFLARE_ACCOUNT_ID: {required: true}
  workflow_dispatch:
    inputs:
      site_key: {description: Registered site key, required: true, type: string}
      launch_key: {description: Exact registered launch for Goyang coverage only, required: false, type: string}
      scope_key: {description: Exact registered scope for Goyang coverage only, required: false, type: string}
      expected_revision: {description: Full preview source commit SHA, required: true, type: string}
  issues:
    types: [opened, reopened]
permissions: {}
concurrency:
  group: site-staging-${{ github.repository }}
  cancel-in-progress: false
